return (() => {
  const p1 = $('PILAR_1').first().json.turnosDisponibles
  const p2 = $('PILAR_2').first().json.turnosDisponibles
  const allTurnos = [...p1, ...p2]

  // Función auxiliar para generar fechaFormato si falta
  function generarFechaFormato(dia) {
    const days = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado']
    const date = new Date(dia + 'T00:00:00')
    const dayName = days[date.getDay()]
    const [year, month, day] = dia.split('-')
    return `${dayName} ${day}/${month}`
  }

  function pick(arr){
    const res=[]
    const days=[...new Set(arr.map(t=>t.dia))]

    // Primero intenta tomar uno por día
    while(res.length<4 && days.length){
      const d=days.splice(Math.floor(Math.random()*days.length),1)[0]
      const opts=arr.filter(t=>t.dia===d)
      if(opts.length)res.push(opts[Math.floor(Math.random()*opts.length)])
    }

    // Si no llegó a 4, completa con turnos de días ya usados
    while(res.length<4){
      const remaining = arr.filter(t => !res.some(r => r.dia === t.dia && r.inicio === t.inicio))
      if(remaining.length === 0) break
      res.push(remaining[Math.floor(Math.random()*remaining.length)])
    }

    // 🔥 AGREGADO: asegurar que siempre exista fechaFormato
    return res.map(t => ({
      dia: t.dia,
      inicio: t.inicio,
      final: t.final,
      Id_Calendario: t.Id_Calendario,
      fechaFormato: t.fechaFormato || generarFechaFormato(t.dia)
    }))
  }

  return [{json: {turnos: pick(allTurnos)}}]
})()

const data = $input.first().json;
const queryData = data.query;

let km, modelo;

// Verificar si es un string con coma
if (typeof queryData === 'string' && queryData.includes(',')) {
    const parts = queryData.split(',');
    km = parts[0].trim(); // Eliminar espacios
    modelo = parts[1].trim();
} else {
    // Si viene en otro formato
    km = queryData;
    modelo = data.modelo || '';
}

return [{json:{query: queryData, km: km, modelo: modelo}}];

return (() => {
    const data = $('Get row(s) in sheet').first().json;
    const queryData = $('When Executed by Another Workflow').first().json.query;

    // Si queryData es un string como "60000,Etios"
    let modelo;

    if (typeof queryData === 'string' && queryData.includes(',')) {
        const parts = queryData.split(',');
        modelo = parts[1].trim();  // Extraer "Etios"
    } else {
        // Si viene en otro formato
        modelo = queryData.modelo || queryData.Modelo || queryData.MODELO;
    }

    // Retornar el tiempo del modelo desde el sheet
    return [{json:{query: data[modelo] ||"1:00:00"}}];
})()

